<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import http from '@/api/http';import { useAuthStore } from '@/stores/auth';import type { Dict } from '@/types'
const auth=useAuthStore(),rows=ref<Dict[]>([]),categories=ref<Dict[]>([]),units=ref<Dict[]>([]),brands=ref<Dict[]>([]),keyword=ref(''),dialog=ref(false)
const form=reactive<Dict>({code:'',name:'',categoryId:'',unitId:'1',brandId:null,specification:'',trackingMode:'QUANTITY',minStock:0,attributes:{}})
const category=computed(()=>categories.value.find(x=>x.id===String(form.categoryId)))
async function load(){[rows.value,categories.value,units.value,brands.value]=await Promise.all([http.get('/materials',{params:{keyword:keyword.value}}),http.get('/material-categories'),http.get('/units'),http.get('/brands')])}
async function save(){await http.post('/materials',form);ElMessage.success('物资已创建');dialog.value=false;await load()}
const tag:Dict={QUANTITY:'info',BATCH:'warning',SERIAL:'success'}
onMounted(load)
</script>
<template><div class="page"><div class="page-head"><div><h1>物资主数据</h1><p>统一管理IT设备、MRO备件与工厂设备</p></div><el-button v-if="auth.can('masterdata:edit')" type="primary" @click="dialog=true">新增物资</el-button></div><div class="panel panel-pad"><div class="toolbar"><el-input v-model="keyword" placeholder="按编码或名称搜索" clearable style="width:280px" @keyup.enter="load"/><el-button @click="load">查询</el-button></div><el-table :data="rows" stripe><el-table-column prop="code" label="物资编码" width="150"/><el-table-column prop="name" label="物资名称" min-width="180"/><el-table-column prop="category" label="分类"/><el-table-column prop="brand" label="品牌"/><el-table-column prop="specification" label="规格" min-width="200"/><el-table-column label="跟踪方式" width="110"><template #default="s"><el-tag :type="tag[s.row.trackingMode]">{{s.row.trackingMode}}</el-tag></template></el-table-column><el-table-column prop="minStock" label="安全库存" width="100"/></el-table></div><el-dialog v-model="dialog" title="新增物资" width="660px"><el-form :model="form" label-width="110px"><div class="grid"><el-form-item label="物资编码"><el-input v-model="form.code"/></el-form-item><el-form-item label="物资名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="分类"><el-select v-model="form.categoryId" style="width:100%"><el-option v-for="x in categories" :key="x.id" :label="x.name" :value="x.id"/></el-select></el-form-item><el-form-item label="计量单位"><el-select v-model="form.unitId" style="width:100%"><el-option v-for="x in units" :key="x.id" :label="x.name" :value="x.id"/></el-select></el-form-item><el-form-item label="品牌"><el-select v-model="form.brandId" clearable style="width:100%"><el-option v-for="x in brands" :key="x.id" :label="x.name" :value="x.id"/></el-select></el-form-item><el-form-item label="库存跟踪"><el-select v-model="form.trackingMode" style="width:100%"><el-option label="数量" value="QUANTITY"/><el-option label="批次" value="BATCH"/><el-option label="序列号" value="SERIAL"/></el-select></el-form-item><el-form-item label="规格型号"><el-input v-model="form.specification"/></el-form-item><el-form-item label="安全库存"><el-input-number v-model="form.minStock" :min="0" style="width:100%"/></el-form-item><el-form-item v-for="a in category?.attributes||[]" :key="a.code" :label="a.name"><el-select v-if="a.valueType==='ENUM'" v-model="form.attributes[a.code]" style="width:100%"><el-option v-for="v in JSON.parse(a.options||'[]')" :key="v" :label="v" :value="v"/></el-select><el-switch v-else-if="a.valueType==='BOOLEAN'" v-model="form.attributes[a.code]"/><el-input-number v-else-if="a.valueType==='NUMBER'" v-model="form.attributes[a.code]" style="width:100%"/><el-input v-else v-model="form.attributes[a.code]"/></el-form-item></div></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<style scoped>.grid{display:grid;grid-template-columns:1fr 1fr;gap:0 14px}</style>
